<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Balloon Bow 95</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  html,body { height:100%; }
  body {
    background:#008080;
    display:flex; align-items:center; justify-content:center;
    font-family:'Press Start 2P', monospace;
    overflow:hidden; user-select:none; -webkit-user-select:none;
  }
  #win {
    background:#c0c0c0;
    border:2px solid; border-color:#dfdfdf #404040 #404040 #dfdfdf;
    box-shadow:2px 2px 0 #000;
    padding:3px;
  }
  #titlebar {
    background:linear-gradient(90deg,#000080,#1084d0);
    color:#fff; font-size:11px; padding:4px 6px;
    display:flex; justify-content:space-between; align-items:center; gap:8px;
    letter-spacing:1px;
  }
  #titlebar .tbtn {
    background:#c0c0c0; color:#000; width:16px; height:14px;
    border:1px solid; border-color:#fff #404040 #404040 #fff;
    font-size:8px; line-height:12px; text-align:center;
  }
  #stage { position:relative; line-height:0; }
  canvas {
    display:block;
    width:min(960px, 92vw);
    image-rendering:pixelated;
    background:#8fd3ff; cursor:crosshair;
  }
  .ov {
    position:absolute; inset:0; display:flex; align-items:center; justify-content:center;
    line-height:1.4;
  }
  .hidden { display:none !important; }
  .dlg {
    background:#c0c0c0;
    border:2px solid; border-color:#dfdfdf #404040 #404040 #dfdfdf;
    box-shadow:3px 3px 0 rgba(0,0,0,.45);
    min-width:340px; padding:3px; text-align:center;
  }
  .dlg-title {
    background:linear-gradient(90deg,#000080,#1084d0);
    color:#fff; font-size:10px; padding:4px 8px; text-align:left; letter-spacing:1px;
  }
  .dlg-body { padding:18px 22px 20px; }
  .big { font-size:20px; color:#000080; margin-bottom:14px; letter-spacing:1px; }
  .ctl { font-size:8px; color:#000; margin:6px 0; text-align:left; display:inline-block; }
  .score-line { font-size:11px; margin:8px 0; }
  .b95 {
    font-family:'Press Start 2P', monospace;
    background:#c0c0c0; color:#000; font-size:11px;
    padding:10px 22px; margin-top:14px; cursor:pointer;
    border:2px solid; border-color:#fff #404040 #404040 #fff;
    box-shadow:1px 1px 0 #000;
  }
  .b95:active { border-color:#404040 #fff #fff #404040; transform:translate(1px,1px); box-shadow:none; }
  .b95:focus { outline:1px dotted #000; outline-offset:-5px; }
  #status {
    display:flex; gap:4px; margin-top:3px; font-size:8px;
  }
  #status > div {
    border:1px solid; border-color:#404040 #fff #fff #404040;
    padding:4px 8px; background:#c0c0c0;
  }
  #st1 { min-width:110px; }
  #st2 { flex:1; text-align:right; }
</style>
</head>
<body>
<div id="win">
  <div id="titlebar"><span>Balloon Bow 95 &mdash; ARCHER.EXE</span><span class="tbtn">&times;</span></div>
  <div id="stage">
    <canvas id="cv" width="960" height="540"></canvas>
    <div id="menu" class="ov">
      <div class="dlg">
        <div class="dlg-title">BALLOON BOW 95</div>
        <div class="dlg-body">
          <div class="big">POP&nbsp;THE&nbsp;BALLOONS!</div>
          <span class="ctl">AIM ......... MOUSE</span><br>
          <span class="ctl">DRAW BOW .... HOLD LMB</span><br>
          <span class="ctl">FIRE ........... RELEASE</span><br>
          <span class="ctl">3 MISSES ..... GAME OVER</span>
          <br>
          <button id="btnStart" class="b95">START</button>
        </div>
      </div>
    </div>
    <div id="over" class="ov hidden">
      <div class="dlg">
        <div class="dlg-title">GAME OVER</div>
        <div class="dlg-body">
          <div class="score-line">SCORE: <span id="fs">0</span></div>
          <div class="score-line" style="font-size:8px;color:#404040">BEST: <span id="bs">0</span></div>
          <button id="btnAgain" class="b95">PLAY AGA
